BURST["dr-where-to-start"] = [
{
"t": "A claim started in the wrong court is not invalid.",
"true": true,
"fix": "Not invalid: the court can **transfer** it (CPR 30) or let it continue."
},
{
"t": "Costs can be cut by up to 25% for starting in the High Court when it should have been the County Court.",
"true": true,
"fix": "The court may reduce recoverable costs by **up to 25%** (Senior Courts Act 1981 s.51(8)-(9))."
},
{
"t": "A judgment of £5,000 or more (not under a regulated consumer credit agreement) must be enforced by taking control of goods in the High Court.",
"true": true,
"fix": "By a **writ of control** executed by a High Court Enforcement Officer (unless a regulated consumer credit agreement)."
},
{
"t": "Court fees depend on value, not on which court.",
"true": true,
"fix": "High Court litigation is generally more expensive, but **court fees depend on value**, not court."
},
{
"t": "Judgments under £600 can only be enforced by taking control of goods in the County Court.",
"true": true,
"fix": "Under **£600**: County Court only."
},
{
"t": "A case can be transferred to a County Court hearing centre in Wales where Welsh is to be used.",
"true": true,
"fix": "Transfers between hearing centres include to a centre in **Wales** where Welsh is to be used."
},
{
"t": "A claim started in the wrong court must be struck out.",
"true": false,
"fix": "**No.** It is not invalid: the court can transfer it (CPR 30) or let it continue."
},
{
"t": "A £3,000 County Court judgment carries statutory judgment interest.",
"true": false,
"fix": "**No.** County Court judgments **under £5,000** generally carry no statutory judgment interest; High Court judgments do."
},
{
"t": "A claim worth more than £100,000 must be issued in the High Court.",
"true": false,
"fix": "**No.** High value alone does not oblige the claimant to use the High Court; many such claims are tried in the County Court."
},
{
"t": "Interest and costs count when valuing a claim for the court thresholds.",
"true": false,
"fix": "**No.** Disregard **interest** and **costs** (CPR 16.3(6))."
}
];
