BURST["sovereignty-rule-of-law"] = [
{
"t": "A court will not enforce the Sewel convention.",
"true": true,
"fix": "True: it is a political convention (Miller 1)."
},
{
"t": "Breaching a convention has political, not legal, consequences.",
"true": true,
"fix": "True: criticism, resignation, loss of office."
},
{
"t": "A court may recognise a convention when deciding a legal issue.",
"true": true,
"fix": "True: as with Cabinet confidentiality."
},
{
"t": "The Ponsonby rule is now in statute.",
"true": true,
"fix": "True: Part 2 Constitutional Reform and Governance Act 2010."
},
{
"t": "Conventions are non-legal rules that those they apply to regard as binding.",
"true": true,
"fix": "True: that is the definition."
},
{
"t": "Jennings' test asks: are there precedents, did the actors feel bound, and is there a reason for the rule?",
"true": true,
"fix": "True: precedents, bound, reason."
},
{
"t": "Writing Sewel into the Scotland Act made it legally enforceable.",
"true": false,
"fix": "False: stating it in statute did not make it enforceable."
},
{
"t": "A court can order a minister to resign for breaching collective responsibility.",
"true": false,
"fix": "False: breach of a convention has political consequences only."
},
{
"t": "Courts will not review the prerogative.",
"true": false,
"fix": "False: courts review the existence, extent and often the exercise of prerogative powers. It is conventions they do not enforce."
},
{
"t": "A Westminster Act on Welsh housing passed without the Senedd's consent is invalid.",
"true": false,
"fix": "False: the Act is valid; Sewel is not legally enforceable."
},
{
"t": "The court stopped a former minister's diaries being published ten years on.",
"true": false,
"fix": "False: it refused an injunction because about ten years had passed."
}
];
