BURST["public-order"] = [
{
"t": "Assemblies need no advance notice.",
"true": true,
"fix": "Right: **no advance notice** is required for an assembly."
},
{
"t": "Since 2022, any necessary conditions can be put on an assembly.",
"true": true,
"fix": "Right: before 2022 only place, maximum duration and maximum numbers."
},
{
"t": "A trespassory assembly ban can last up to four days within five miles.",
"true": true,
"fix": "Right: up to **four days**, radius up to **five miles**."
},
{
"t": "A peaceful, non-obstructive assembly on a highway can be a reasonable use of it.",
"true": true,
"fix": "Right: so it is not trespassory (DPP v Jones)."
},
{
"t": "Conditions can be put on a one-person protest whose noise may cause serious disruption.",
"true": true,
"fix": "Right: s.14ZA."
},
{
"t": "Causing public nuisance intentionally or recklessly is now a statutory offence.",
"true": true,
"fix": "Right: the PCSCA 2022 replaced the common law offence."
},
{
"t": "Locking on to cause serious disruption is an offence.",
"true": true,
"fix": "Right: Public Order Act 2023."
},
{
"t": "The police can ban a static rally under s.13.",
"true": false,
"fix": "**No.** s.13 bans apply only to processions; only trespassory assemblies can be banned (s.14A)."
},
{
"t": "An assembly needs six clear days' notice.",
"true": false,
"fix": "**No.** Six clear days is for processions; assemblies need no notice."
},
{
"t": "A trespassory assembly is any group of 5 people.",
"true": false,
"fix": "**No.** It needs **20 or more** people, on land with no or limited public access."
},
{
"t": "Safe access zones around abortion clinics are 500 metres wide.",
"true": false,
"fix": "**No.** They are **150 metres**."
}
];
