BURST["consideration"] = [
{
"t": "Early payment counts only if it is at the creditor's request.",
"true": true,
"fix": "True: paying **early** or at a **different place** only counts if it was at the creditor's request."
},
{
"t": "Promissory estoppel fails if the promise was got by pressure.",
"true": true,
"fix": "True: it is not inequitable to go back on a promise got by **pressure or intimidation**."
},
{
"t": "The promisor can usually return to full rights for the future on reasonable notice.",
"true": true,
"fix": "True: promissory estoppel is usually **suspensory**."
},
{
"t": "Promissory estoppel needs an existing legal relationship between the parties.",
"true": true,
"fix": "True: usually a contract, such as a lease or a loan."
},
{
"t": "A promise in a deed is binding without consideration.",
"true": true,
"fix": "True: a deed needs **no consideration**."
},
{
"t": "Promissory estoppel lets you sue on a free promise.",
"true": false,
"fix": "False: it is a **shield, not a sword**; it cannot create a new cause of action."
},
{
"t": "Promissory estoppel ends the promisor's rights for the future for ever.",
"true": false,
"fix": "False: it usually only **suspends** them until reasonable notice is given."
},
{
"t": "Practical benefit defeats a claim for the balance of a debt.",
"true": false,
"fix": "False: practical benefit helps a promise to **pay more**, never a debtor who pays **less**."
},
{
"t": "Paying by cheque instead of cash is something different.",
"true": false,
"fix": "False: a cheque is **not** something different."
},
{
"t": "A vague or ambiguous statement is enough for promissory estoppel.",
"true": false,
"fix": "False: the promise must be **clear and unequivocal**."
}
];
