BURST["intention-certainty-capacity"] = [
{
"t": "A guarantor of a minor's contract can be liable.",
"true": true,
"fix": "True: the Minors' Contracts Act 1987 **s.2**."
},
{
"t": "\"Subject to contract\" can be waived by conduct.",
"true": true,
"fix": "True: the parties can **waive** it by their conduct."
},
{
"t": "A drunk person's contract is voidable only if the other party knew or ought to have known.",
"true": true,
"fix": "True: otherwise it binds."
},
{
"t": "A company's capacity is not limited by its constitution.",
"true": true,
"fix": "True: Companies Act 2006 **s.39**."
},
{
"t": "An agreement to agree the price is not a binding contract.",
"true": true,
"fix": "True: a key term has been left for future agreement."
},
{
"t": "A meaningless phrase can be cut out, leaving a valid contract.",
"true": true,
"fix": "True: a meaningless subsidiary phrase can be **severed**."
},
{
"t": "A letter of comfort is never binding.",
"true": false,
"fix": "False: it **depends on the words**; a clear promise can bind."
},
{
"t": "\"Ex gratia\" stops a business promise being binding.",
"true": false,
"fix": "False: in a commercial setting \"ex gratia\" was **not enough**."
},
{
"t": "A minor pays the agreed price for necessaries.",
"true": false,
"fix": "False: a **reasonable price**, not the agreed price."
},
{
"t": "A minor's trading contract binds the minor if it is beneficial.",
"true": false,
"fix": "False: trading contracts are **not binding** even if beneficial."
}
];
