BURST["mistake-duress-ui-illegality"] = [
{
"t": "Misrepresentation, duress and undue influence make a contract voidable.",
"true": true,
"fix": "True."
},
{
"t": "A bank that got the solicitor's written confirmation is usually protected even if the advice was poor.",
"true": true,
"fix": "True: the wife's remedy is against her solicitor."
},
{
"t": "An unreasonable part of a restraint can be cut out if no rewriting is needed.",
"true": true,
"fix": "True: severance."
},
{
"t": "A joint loan for both spouses' benefit does not put the bank on inquiry.",
"true": true,
"fix": "True, unless the bank knows it is really for the husband alone."
},
{
"t": "Money paid under an illegal contract can usually be recovered in unjust enrichment.",
"true": true,
"fix": "True, unless the trio of considerations points the other way."
},
{
"t": "Mistake makes a contract voidable.",
"true": false,
"fix": "False: where mistake operates, the contract is void."
},
{
"t": "Husband and wife is an automatic relationship of trust.",
"true": false,
"fix": "False: it must be proved on the facts."
},
{
"t": "A lawful refusal to deal is usually duress.",
"true": false,
"fix": "False: lawful act duress is very rare."
},
{
"t": "Paying under pressure and waiting eight months still lets you rescind.",
"true": false,
"fix": "False: waiting that long without protest affirms the contract."
},
{
"t": "Mere protection from competition is a legitimate interest.",
"true": false,
"fix": "False: trade secrets, customer connections or goodwill are needed."
}
];
