BURST["wills/family-provision"] = [
{
"t": "The 6-month time limit runs from the date of the grant.",
"true": true,
"fix": "Right: **6 months from the date of the grant** of representation."
},
{
"t": "The 6 months runs from the date of death.",
"true": false,
"fix": "No: it runs from the **grant**, not from death."
},
{
"t": "A claim can be made before a grant is issued.",
"true": true,
"fix": "Right: allowed **since 2014**."
},
{
"t": "The court can allow a late claim.",
"true": true,
"fix": "Right: the court has a **discretion to extend** the time."
},
{
"t": "PRs who distribute after 6 months from the grant are not personally liable if a late claim is later allowed.",
"true": true,
"fix": "Right: **s.20** protects them."
},
{
"t": "Once the estate has been distributed, nothing can be recovered for a late claim.",
"true": false,
"fix": "No: the court can still **recover property from beneficiaries**."
},
{
"t": "A cohabitant gets the maintenance standard.",
"true": true,
"fix": "Right: everyone except spouses and civil partners gets the **maintenance standard**."
},
{
"t": "Adult children get the spouse standard.",
"true": false,
"fix": "No: only spouses and civil partners get it. Adult children get the **maintenance standard**."
},
{
"t": "The spouse standard is what is reasonable in all the circumstances, whether or not it is needed for maintenance.",
"true": true,
"fix": "Right: s.1(2)(a)."
},
{
"t": "What the spouse would get on divorce is a floor for the award.",
"true": false,
"fix": "No: the divorce figure is a **cross-check**, neither a floor nor a ceiling."
},
{
"t": "The maintenance standard gives capital for its own sake.",
"true": false,
"fix": "No: money for the **day-to-day costs of living**, not capital for its own sake or an inheritance."
}
];
