BURST["trusts/trustee-duties-powers"] = [
{
"t": "For a trust from after 1 October 2014, trustees may use income for a minor as they think fit.",
"true": true,
"fix": "**True.** The 2014 Act removed the reasonableness test."
},
{
"t": "Surplus income not used during minority is accumulated.",
"true": true,
"fix": "**True.** s.31(2): invested and added to capital."
},
{
"t": "At 18 a contingent beneficiary gets the income of their share as of right, not the capital.",
"true": true,
"fix": "**True.** s.31(1)(ii), until the interest vests or fails."
},
{
"t": "s.31 applies only if the gift carries the intermediate income.",
"true": true,
"fix": "**True.** And only if the trust instrument does not exclude it."
},
{
"t": "s.31 lets trustees hand a minor part of the capital.",
"true": false,
"fix": "**False.** s.31 is about income; capital early is advancement under s.32."
},
{
"t": "Before 2014 trustees could pay a minor whatever income they liked.",
"true": false,
"fix": "**False.** For pre-2014 trusts the payment had to be reasonable, considering other income."
},
{
"t": "A professional trustee is held to a higher standard of care than a lay trustee.",
"true": true,
"fix": "**True.** s.1: objective, with a sliding scale."
},
{
"t": "s.8 lets trustees buy land anywhere in the world.",
"true": false,
"fix": "**False.** s.8 covers only land in the United Kingdom."
},
{
"t": "Trustees need not take advice if they reasonably conclude it is unnecessary or inappropriate.",
"true": true,
"fix": "**True.** s.5(3), for example a small sum."
},
{
"t": "A trustee is liable for every default of an agent.",
"true": false,
"fix": "**False.** Only if the trustee failed the duty of care in appointing or reviewing (s.23)."
},
{
"t": "Trustees of a discretionary trust must give reasons for their decisions.",
"true": false,
"fix": "**False.** They need not give reasons."
}
];
BOARD_HOOKS["trusts/trustee-duties-powers"] = ["Trustee duties", "Duty of care", "Take advice", "Income: section 31", "Capital: section 32"];
