BURST["trusts/breach-of-trust"] = [
{
"t": "Paying the wrong beneficiary by an honest mistake is a breach of trust.",
"true": true,
"fix": "**True.** Innocent breaches count too."
},
{
"t": "Investing in overseas land with no express power is a breach.",
"true": true,
"fix": "**True.** An unauthorised investment."
},
{
"t": "Never reviewing the investments is a breach.",
"true": true,
"fix": "**True.** TA 2000 s.4 requires review."
},
{
"t": "Letting a co-trustee control all the money and doing nothing is itself a breach.",
"true": true,
"fix": "**True.** Standing by is a breach."
},
{
"t": "Taking trust property for yourself is a breach.",
"true": true,
"fix": "**True.** Misappropriation."
},
{
"t": "A retired trustee stays liable for breaches committed while in office.",
"true": true,
"fix": "**True.**"
},
{
"t": "A new trustee is liable for breaches committed before they were appointed.",
"true": false,
"fix": "**False.** Not liable, but they should investigate and act on them."
},
{
"t": "A trustee is liable for a co-trustee's breach they had nothing to do with.",
"true": false,
"fix": "**False.** Liable only for their own breaches (standing by counts as their own)."
},
{
"t": "Only a deliberate failure counts as a breach of trust.",
"true": false,
"fix": "**False.** Deliberate, careless or innocent."
},
{
"t": "A trustee in breach pays the loss out of the trust fund, not personally.",
"true": false,
"fix": "**False.** The trustee is personally liable, out of their own pocket."
}
];
