BURST["land/covenants"] = [
{
"t": "The burden of a restrictive covenant can run in equity.",
"true": true,
"fix": "Right: under Tulk v Moxhay, if the four requirements are met."
},
{
"t": "s.79 presumes the burden was intended to run.",
"true": true,
"fix": "Right: for post-1925 covenants, unless a contrary intention appears."
},
{
"t": "s.78 can annex the benefit to each and every part of the land.",
"true": true,
"fix": "Right: statutory annexation."
},
{
"t": "The Upper Tribunal can modify a covenant that is obsolete.",
"true": true,
"fix": "Right: ground (a)."
},
{
"t": "The original covenantor can stay liable after selling.",
"true": true,
"fix": "Right: s.79, unless limited to the period of ownership."
},
{
"t": "One person coming to own both plots extinguishes the covenant.",
"true": true,
"fix": "Right: unity of seisin."
},
{
"t": "The burden of a positive covenant runs if it is noted on the register.",
"true": false,
"fix": "No: it never runs; a notice protects only interests capable of binding."
},
{
"t": "A buyer who knew about an unprotected restrictive covenant over registered land is bound.",
"true": false,
"fix": "No: a buyer for value who registers takes free if it was not noted (s.29)."
},
{
"t": "A developer who deliberately builds first will usually get the covenant modified.",
"true": false,
"fix": "No: a deliberate breach weighs heavily against it."
},
{
"t": "The Upper Tribunal can discharge a positive covenant under s.84.",
"true": false,
"fix": "No: s.84 applies to restrictive covenants."
}
];
