BURST["land/leases-remedies"] = [
{
"t": "A landlord can only forfeit if the lease has a right of re-entry.",
"true": true,
"fix": "Right: without one, no forfeiture however serious the breach."
},
{
"t": "Accepting rent due after the breach, knowing of it, waives the right to forfeit.",
"true": true,
"fix": "Right: the most common act of waiver."
},
{
"t": "A demand marked \"without prejudice\" still waives.",
"true": true,
"fix": "Right: it is still an unequivocal act."
},
{
"t": "After waiving a continuing breach the landlord can forfeit for it later.",
"true": true,
"fix": "Right: the breach recurs every day; waiver covers only the past."
},
{
"t": "Once a once-and-for-all breach is waived, the right to forfeit for it is lost for good.",
"true": true,
"fix": "Right: e.g. assigning without consent."
},
{
"t": "Serving a possession claim is an election to forfeit.",
"true": true,
"fix": "Right: the lease is treated as ended from service, subject to relief."
},
{
"t": "A residential landlord can change the locks to forfeit while the tenant lives there.",
"true": false,
"fix": "No: unlawful (PEA 1977 s.2) and possibly the offence of unlawful eviction."
},
{
"t": "Waiver stops the landlord suing for the arrears.",
"true": false,
"fix": "No: it can still sue for damages or arrears."
},
{
"t": "The managing agent's knowledge does not count.",
"true": false,
"fix": "No: the landlord's knowledge includes its agents'."
},
{
"t": "Peaceable re-entry needs a court order.",
"true": false,
"fix": "No: it is retaking possession without a court order (commercial premises only)."
}
];
