BURST["property/lta1954"] = [
{
"t": "The landlord's intention under ground (f) is judged at the hearing",
"true": true,
"fix": "**True.**"
},
{
"t": "A landlord who bought 3 years ago cannot rely on ground (g)",
"true": true,
"fix": "**True.** The 5-year rule."
},
{
"t": "Grounds (d), (f) and (g) succeed if proved",
"true": true,
"fix": "**True.** They are mandatory if proved."
},
{
"t": "Persistent late rent is a discretionary ground",
"true": true,
"fix": "**True.** Ground (b) is discretionary."
},
{
"t": "The tenant can defeat ground (f) by agreeing to give access for the works",
"true": true,
"fix": "**True.** s.31A."
},
{
"t": "A landlord who would only do the works if the tenant refused to leave satisfies ground (f)",
"true": false,
"fix": "**False.** The intention must not depend on whether the tenant leaves: the landlord must intend the works even if the tenant goes voluntarily."
},
{
"t": "The court has a discretion to refuse ground (f) even if proved",
"true": false,
"fix": "**False.** Ground (f) is mandatory if proved."
},
{
"t": "A landlord who never served a counter-notice to a s.26 request can still oppose later",
"true": false,
"fix": "**False.** Without a counter-notice within 2 months it cannot later oppose renewal."
},
{
"t": "Ground (g) covers a landlord who wants to occupy as its home",
"true": true,
"fix": "**True.** Own business or residence."
},
{
"t": "Disrepair (ground (a)) wins automatically once proved",
"true": false,
"fix": "**False.** It is discretionary: the court must also think the tenant ought not to have a new tenancy."
}
];
