/* bullets-sample: preview flag + splitter (no wording changes: only cuts the existing text at sentence ends) */
function bulletsOn(){ return true; } /* 23:46 Monnie approved: sweet bullets live in every jar */
function bulSplit(html){
  /* numbered lists ("1. ... 2. ..."): one bullet per number, the number stays inline with its text */
  var nre = /(?:^|<br\s*\/?>|\n|\s)(\d{1,2})\.\s+(?=\S)/g, nm, cuts = [];
  while ((nm = nre.exec(html))){ var want = cuts.length + 1; if (+nm[1] === want) cuts.push(nm.index + nm[0].indexOf(nm[1])); }
  if (cuts.length >= 2){
    var lead = html.slice(0, cuts[0]).replace(/(<br\s*\/?>|\s)+$/,'').trim(), items = lead ? [lead] : [];
    cuts.forEach(function(c, i){ items.push(html.slice(c, i + 1 < cuts.length ? cuts[i + 1] : html.length).replace(/(<br\s*\/?>|\s)+$/,'').trim()); });
    return items.filter(function(s){ return s; });
  }
  if (/^\s*\d{1,2}\.[\s\u200B]+\S/.test(html)) return [html.trim()]; /* one numbered line (own paragraph): keep it whole */
  var out = [], start = 0, re = /([.?!])((?:<\/(?:b|strong|em|i)>)*)(\s+)(?=[A-Z'‘"“(<])/g, m;
  while ((m = re.exec(html))){
    var end = m.index + 1 + m[2].length, head = html.slice(0, end);
    var depth = (head.match(/<(b|strong|em|i)(\s[^>]*)?>/g) || []).length - (head.match(/<\/(b|strong|em|i)>/g) || []).length;
    var w = (html.slice(0, m.index).match(/([A-Za-z.]+)$/) || ['', ''])[1];
    if (depth || /^(s|ss|e\.g|i\.e|cf|v|vs|para|art|reg|Mr|Mrs|Ms|Dr|St)$/i.test(w) || /(^|[>\n])\s*\d{1,3}$/.test(html.slice(0, m.index))) continue;
    out.push(html.slice(start, end).trim()); start = end + m[3].length;
  }
  out.push(html.slice(start).trim());
  return out.filter(function(s){ return s; });
}
function bulletize(cardHTML){
  try {
    var tmp = document.createElement('div'); tmp.innerHTML = cardHTML;
    [].forEach.call(tmp.querySelectorAll('.lrn-body, .lrn-cs > div'), function(box){
      var ps = box.querySelectorAll(':scope > p'), parts = [];
      if (ps.length){ if (ps.length !== box.children.length) return; [].forEach.call(ps, function(p){ parts = parts.concat(bulSplit(p.innerHTML)); }); }
      else parts = bulSplit(box.innerHTML);
      if (parts.length < 2) return;
      box.innerHTML = '<ul class="scn-bul">' + parts.map(function(s){ return '<li>' + s + '</li>'; }).join('') + '</ul>';
    });
    return tmp.innerHTML;
  } catch(e){ return cardHTML; }
}

