    '.cw .ch{display:inline-block;position:relative;clip-path:inset(-20% 100% -20% 0);animation:cwL var(--cwd,.11s) linear forwards;animation-delay:var(--cwt,0s)}' +
    '.cw .ch::after{content:"";position:absolute;right:-.06em;bottom:.12em;width:.16em;height:.16em;border-radius:50%;background:currentColor;box-shadow:0 0 .12em currentColor;opacity:0;animation:cwN var(--cwd,.11s) linear;animation-delay:var(--cwt,0s)}' +
    '@keyframes cwL{to{clip-path:inset(-20% -10% -20% -10%)}}@keyframes cwN{0%,100%{opacity:0}10%,90%{opacity:.95;transform:translateY(-.25em)}50%{transform:translateY(.1em)}}' +
    '@media (prefers-reduced-motion:reduce){.cw .ch{animation:none;clip-path:none}.cw .ch::after{display:none}}';
