  function run(bt){ var lns = [].slice.call(bt.querySelectorAll('.ln')); if (!lns.length) return;
    var vis = lns.filter(function(l){ return bt.closest('.paged') ? l.classList.contains('on') : true; }), t = 0.15;
    vis.forEach(function(ln){ split(ln); ln.classList.remove('cw'); void ln.offsetWidth; ln.classList.add('cw');
      [].forEach.call(ln.querySelectorAll('.ch'), function(ch){ ch.style.setProperty('--cwt', t.toFixed(3) + 's'); t += PER; }); t += GAP; }); }
  var seen = typeof WeakMap === 'function' ? new WeakMap() : null;
  function key(bt){ return [].map.call(bt.querySelectorAll('.ln'), function(l){ return l.classList.contains('on') ? 1 : 0; }).join(''); }
  function scan(){ [].forEach.call(document.querySelectorAll('.scn-board .scn-bt'), function(bt){
      var k = key(bt) + '|' + bt.textContent.length; if (seen && seen.get(bt) === k) return; if (seen) seen.set(bt, k); run(bt); }); }
