      (away ? '' : '<span class="jcbrit" id="jcBrit" role="img" aria-label="Britney" style="left:-6%"><span class="lbr jclbr">' + ['f1', 'f2', 'bb', 'bh'].map(function(c){ return '<img class="' + c + '" src="img/britney/set/neutral.webp" alt="">'; }).join('') + '</span><img class="hp" src="img/britney/set/happy.webp" alt=""></span>');
    setTimeout(jcWalk, 0); setTimeout(jcWalk, 120);
