  function bertScene(){ /* v3 (Monnie 20 Nov 06:49): taller scene, the path winds down the hill; scene img/scene/berts-scene2.webp (art-src/berts-scene-tall-gemini.jpeg).
     Layla runs with two stride frames (img/layla-run-1/2.webp), Britney flies ahead at shoulder height, Bert chases with his cleaver. Routes: tools in styles.css "b3" keyframes */
    return '<div class="bscene3" role="img" aria-label="Bert comes out of his butcher\'s shop and chases Layla and Britney down the winding path"><img class="bs3-bg" src="img/scene/berts-scene2.webp" alt="" width="1400" height="1400"><span class="bs3-door"></span>' +
      '<span class="b3 b3-brit"><span class="fl"><img class="a" src="img/britney/fly1.webp" alt=""><img class="b" src="img/britney/fly3.webp" alt=""></span></span>' +
      '<span class="b3 b3-lay"><span class="fl"><img class="i0" src="img/layla-walk-1.webp" alt=""><span class="run">' + runHTML('layla') + '</span></span></span>' +
      '<span class="b3 b3-bert"><span class="fl">' + runHTML('bert') + '</span><b class="sh">Oi! Come back here!</b></span></div>';
  }
  var BT = null; /* {sid, items, i, right, pick, ord, paid} */
  function viewButcher(r){
    var h = top('butcher').replace('class="cbag town"', 'class="cbag town tb-red"'), sid = r[2], s = sid && subj(sid);
    if (s && BT && BT.sid === sid) return h + bertRun(s) + '</div>';
    if (s) return h + bertIntro(s) + '</div>';
    h = h.replace('class="cbag town tb-red"', 'class="cbag town tb-red town-sh"');
    var away = window.SQE_BRIT_AWAY && window.SQE_BRIT_AWAY();
    if (away && window.SQE_BOSS_PANEL) h += window.SQE_BOSS_PANEL(); /* Monnie 20 Nov: while Bert has Britney his page shows her in his window, not the chase */
    else h += '<div class="bcard">' + bertScene() + '<div class="town-bert town-bertlogo"><div class="bblogo" aria-hidden="true"><span class="sb">BERT\'S<br>BUTCHERS</span><span class="aw"></span></div><div><h2>Bert\'s Butchers</h2><div class="bspeech">"Learned a whole subject, have you? Then you sit my test. ' + Math.round(BERT_PASS * 100) + '% to pass, and I\'ll be marking."</div></div></div></div>';
    var B = bertS();
    /* Monnie 20 Nov 08:25: the top of Bert's shop = exactly the Bert steps on Today's list */
    var tdF = window.SQE_TODAY_BERT ? window.SQE_TODAY_BERT() : [], pdT = A.planDay(A.ymd()), tdS = pdT ? bertDue(pdT) : [];
    h += '<div class="bcard tb-today"><h3>On today\'s list</h3>' + (tdF.length || tdS.length ? '<ul class="town-subj">' +
      tdF.map(function(f){ return '<li class="' + (f.won ? 'pass' : '') + '"><span class="sn"><b>Face the Butcher: ' + esc(f.title) + '</b><span>' + (f.won ? '✓ Beaten' : '10 questions on this topic') + '</span></span>' + (away ? '<span class="small muted">Rescue Britney first</span>' : '<a class="btn' + (f.won ? '' : ' primary') + '" href="' + f.href + '">' + (f.won ? 'Practise again' : 'Face him') + '</a>') + '</li>'; }).join('') +
      tdS.map(function(b){ var k = 'bert|' + pdT.d + '|' + b.s.id, dn = !!(S().todo && S().todo[k]); return '<li class="' + (dn ? 'pass' : '') + '"><span class="sn"><b>Subject test: ' + esc(b.s.title) + '</b><span>' + (dn ? '✓ Done today' : bertSize(b.s) + ' questions on the whole subject') + '</span></span>' + (away ? '<span class="small muted">Rescue Britney first</span>' : '<a class="btn primary" href="#/town/butcher/' + b.s.id + '">Sit the test</a>') + '</li>'; }).join('') + '</ul>'
      : '<p class="town-note" style="margin:0">Nothing from Bert on today\'s list.</p>') + '</div>';
    /* Monnie 20 Nov 08:10: one place that explains Bert's two games, so Today's "Face the Butcher" step and this page match */
    /* Monnie 20 Nov 13:15: the 'Bert's two games' explainer card removed (it added nothing for Layla) */
    h += '<div class="bcard"><h3>Subject tests</h3><p class="town-note" style="margin:0 0 10px">Best sat once you\'ve learned all its topics. Pass mark ' + Math.round(BERT_PASS * 100) + '%. First pass: +' + BERT_PASS_COINS + ' coins.</p><ul class="town-subj">' + A.SUBJ.map(function(s){
      var rec = B[s.id], ok = true /* Monnie 20 Nov: never locked */, fin = subjDone(s), dn = s.topics.filter(function(t){ return learned(s.id + '/' + t.id); }).length;
      return '<li class="' + (rec && rec.passed ? 'pass' : ok ? '' : 'locked') + '"><span class="sn"><b>' + esc(s.title) + '</b><span>' + (rec && rec.passed ? '✓ Passed · best ' + rec.best + '%' : rec ? 'Not passed yet · best ' + rec.best + '%' : bertSize(s) + ' questions' + (fin ? ' · all topics learned' : ' · ' + dn + ' of ' + s.topics.length + ' topics learned')) + '</span></span>' +
        (ok ? '<a class="btn' + (rec && rec.passed ? '' : ' primary') + '" href="#/town/butcher/' + s.id + '">' + (rec && rec.passed ? 'Practise again' : rec ? 'Try again' : 'Sit the test') + '</a>' : '<span class="small muted">Locked</span>') + '</li>';
    }).join('') + '</ul></div>';
    /* (Face the Butcher, the per-topic game, is no longer listed here: it stays at the bottom of each topic's notes. Monnie 20 Nov) */
    return h + '</div>';
  }
  function bertIntro(s){
    var rec = bertS()[s.id], back = '<a class="btn" href="#/town/butcher">Back to the shop</a>';
    var n = bertSize(s);
    if (window.SQE_BRIT_AWAY && window.SQE_BRIT_AWAY() && window.SQE_BOSS_PANEL) return window.SQE_BOSS_PANEL() + '<div class="btns">' + back + '</div>'; /* no new test while Bert has her */
    if (!n) return '<div class="bcard"><h2>' + esc(s.title) + ' test</h2><p>Bert is still writing this test. Check back soon.</p><div class="btns">' + back + '</div></div>';
    return '<div class="bcard town-bert"><img src="img/boss/bert-knife.webp" alt="Bert the butcher" width="612" height="800"><div><h2>' + esc(s.title) + ': Bert\'s test</h2><div class="bspeech">"' + n + ' questions on ' + esc(s.title) + '. Get ' + Math.ceil(n * BERT_PASS) + ' right to pass."</div>' +
      (rec ? '<p class="small">Your best so far: <b>' + rec.best + '%</b>' + (rec.passed ? ' (passed)' : '') + '.</p>' : '') + '<div class="btns"><button type="button" class="btn primary" data-town="btstart" data-s="' + s.id + '">Start the test</button>' + back + '</div></div></div>';
  }
  function bertItem(q){ return {text: '<div class="town-q notes">' + md(q.q) + '</div>', opts: q.o.map(function(o){ return inl(o); }), a: q.a, why: md(q.e || ''), lab: ''}; }
  function bertRun(s){
    var b = BT;
    if (!b.chased && b.i === 0 && b.pick == null && window.SQE_BERT_CHASE){ /* Monnie 20 Nov: the chase plays before Bert's subject test too */
      var ms = window.SQE_BERT_CHASE_MS || 5200, left = Math.max(0, (b.chaseAt || (b.chaseAt = Date.now())) + ms - Date.now());
      if (left){ setTimeout(function(){ if (BT === b && !b.chased){ b.chased = 1; A.render(); } }, left + 50);
        return '<div class="bcard bossg">' + window.SQE_BERT_CHASE() + '<p style="text-align:center;margin:10px 0 0">Uh oh! Bert wants Britney! ' + b.items.length + ' questions on ' + esc(s.title) + ' to keep him away.</p><div class="btns" style="justify-content:center"><button type="button" class="btn primary" data-town="btchase">Skip ›</button></div></div>'; }
      b.chased = 1;
    }
    if (b.i >= b.items.length){
      var pct = Math.round(b.right / b.items.length * 100), pass = b.right >= Math.ceil(b.items.length * BERT_PASS);
      return '<div class="bcard" style="text-align:center"><img src="img/boss/bert-knife.webp" alt="" width="612" height="800" style="width:90px;height:auto;margin:0 auto"><h2>' + (pass ? 'You passed Bert\'s test!' : b.grabbed ? 'Bert grabbed Britney!' : 'Not this time') + '</h2><p style="font-size:19px">' + b.right + ' of ' + b.items.length + ' right (' + pct + '%). Pass mark ' + Math.round(BERT_PASS * 100) + '%.' + (b.paid ? ' <b>+' + b.paid + ' coins</b>.' : '') + '</p><p>' + (pass ? '"Hmph. Fair enough. You know your ' + esc(s.title) + '."' : (b.grabbed ? '"Mwahaha! ' + btMax(b) + ' wrong and she\'s mine. She\'s going in my shop window."' + (b.took ? ' Get the questions you missed right to win her back.' : '') : '"Back to the notes with you, then try again."')) + '</p><div class="btns" style="justify-content:center">' + (b.took ? '<a class="btn primary" href="#/boss/rescue">Get Britney back</a>' : '<button type="button" class="btn' + (pass ? '' : ' primary') + '" data-town="btstart" data-s="' + s.id + '">' + (pass ? 'Practise again' : 'Try again') + '</button>') + '<button type="button" class="btn' + (pass ? ' primary' : '') + '" data-town="btquit">Back to the shop</button></div></div>';
    }
    /* Monnie 20 Nov: a way back to the shop, a way back to earlier questions (to look again: answers are locked once Bert has moved),
       and Bert creeping towards Britney above every question */
    var m = btMax(b), nav = '<div class="btnav"><a class="btn sm" href="#/town/butcher">‹ Bert\'s Butchers</a>';
    if (b.view != null){
      var lg = b.log[b.view], rv = bertItem(b.items[b.view]); rv.ord = lg.ord; rv.pick = lg.pick; rv.lab = s.title;
      nav += (b.view > 0 ? '<button type="button" class="btn sm" data-town="btprev">‹ Previous question</button>' : '') + '</div>';
      return nav + btStrip(b, true) + qCard(rv, b.view + 1, b.items.length, 'btnone', 'btfwd', b.view + 1 >= b.i ? 'Back to question ' + (b.i + 1) + ' ›' : 'Next question ›', '<p class="town-note">Looking back: answers are locked once given.</p>');
    }
    nav += (b.i > 0 ? '<button type="button" class="btn sm" data-town="btprev">‹ Previous question</button>' : '') + '</div>';
    var it = bertItem(b.items[b.i]); it.ord = b.ord; it.pick = b.pick; it.lab = s.title;
    if (b.grabNow) return nav + btStrip(b) + '<div class="btns" style="justify-content:center;margin-top:14px"><button type="button" class="btn primary big" data-town="btnext">See what happened ›</button></div>';
    return nav + btStrip(b) + (window.SQE_BTIMER ? window.SQE_BTIMER('t' + b.sid + ':' + b.i, b.pick != null) : '') + qCard(it, b.i + 1, b.items.length, 'btpick', 'btnext', b.i + 1 >= b.items.length ? ((b.wrong || 0) >= m ? 'Uh-oh… ›' : 'See my score') : 'Next question ›', '<p class="town-note">' + b.right + ' right so far. ' + Math.ceil(b.items.length * BERT_PASS) + ' right to pass.</p>');
  }
  /* wrong answers that make Bert grab Britney: more than 40% wrong (9 of 20), so he steps 1/9 of the way per wrong answer */
  function btMax(b){ var n = b.items.length; return n - Math.ceil(n * BERT_PASS) + 1; }
  function btStrip(b, still){
    var m = btMax(b), grab = !!b.grabNow, w = grab ? m : Math.min(b.wrong || 0, m - 1), pw = still || b.shownW == null ? w : Math.min(b.shownW, m); /* Monnie 16:22: Bert waits beside Britney and only grabs her after the last question */
    var at = function(x){ return (1 - x / m).toFixed(3); }, near = w / m, left = m - w;
    var h = '<div class="btstrip' + (still && grab ? ' grab done' : '') + '" id="btstrip" style="--p:' + at(pw) + ';--ta:' + (1 + 5 * near).toFixed(1) + 'px;--tr:' + (1.5 + 8 * near).toFixed(1) + 'deg;--ts:' + (.5 - .38 * near).toFixed(2) + 's" role="img" aria-label="Bert is ' + left + ' steps from Britney">' +
      '<span class="bts-brit"><img src="img/britney/' + ['set/neutral', 'fear1', 'fear2', 'fear3', 'terrified'][w ? Math.min(4, Math.ceil(near * 4)) : 0] + '.webp" alt=""></span>' + /* Monnie 20 Nov 09:49: fear builds gradually */
      '<span class="bts-bert"><span class="bb"><span class="bkw"><span class="bk bkrig">' + runHTML('bert') + '</span><img class="bktd" src="img/boss/bert-td-body.webp" alt=""><img class="bka" src="img/boss/bert-td-arm.webp" alt=""></span><img class="bc" src="img/britney/terrified.webp" alt=""></span></span>' +
      '<span class="bts-n">' + (grab ? 'Bert grabbed Britney!' : (b.wrong || 0) >= m ? 'Bert is right beside Britney…' : (b.wrong || 0) + ' wrong · ' + (m - (b.wrong || 0)) + ' more and Bert grabs Britney') + '</span></div>';
    if (!still && pw !== w){ b.shownW = w; setTimeout(function(){ var e = document.getElementById('btstrip'); if (!e) return; e.style.setProperty('--p', at(w)); if (grab) setTimeout(function(){ e.classList.add('grab'); }, 700); }, 60); }
    else b.shownW = w;
    return h;
  }
  function btOrd(){ var q = BT.items[BT.i]; BT.ord = q ? A.shuffle(q.o.map(function(o, i){ return i; })) : []; BT.pick = null; }
  function btFinish(){
    var b = BT, pct = Math.round(b.right / b.items.length * 100), pass = b.right >= Math.ceil(b.items.length * BERT_PASS), B = bertS(), rec = B[b.sid] || {best: 0, passed: false};
    B[b.sid] = {best: Math.max(rec.best || 0, pct), passed: !!(rec.passed || pass), date: A.ymd()};
    if (pass) b.paid = A.earn(BERT_PASS_COINS, 'bertpass|' + b.sid, true);
    else if (b.grabbed && window.SQE_BERT_TAKE){ /* Monnie 20 Nov: the grab is saved, the questions she missed become the rescue */
      var miss = []; (b.log || []).forEach(function(lg, i){ var q = b.items[i]; if (lg && q && lg.pick !== q.a) miss.push({kind: 'qa', id: q.id, q: q.q, o: q.o, a: q.a, e: q.e, tk: b.sid + '/' + q.t}); });
      b.took = window.SQE_BERT_TAKE(miss, '');
    }
    var t = S(); t.todo = t.todo || {}; var k = 'bert|' + A.ymd() + '|' + b.sid; if (!t.todo[k]) t.todo[k] = Date.now(); /* ticks the timetable slot if it's today */
    A.save();
  }

  /* ---------- Hen Bargains + gamble ---------- */
  function sraAll(){ return ((window.SQE_SRA || {}).questions || []).filter(function(q){ return q && q.id && q.stem && q.options && q.answer; }); }
  function sraPool(){ /* GAMBLE_N SRA sample questions at random, learned subjects first */
    var Q = sraAll(), known = {};
    A.SUBJ.forEach(function(s){ if (s.topics.some(function(t){ return learned(s.id + '/' + t.id); })) known[s.id] = 1; });
    return A.shuffle(Q.filter(function(q){ return known[q.subject]; })).concat(A.shuffle(Q.filter(function(q){ return !known[q.subject]; }))).slice(0, GAMBLE_N);
  }
  function prices(it){ return {lo: it.p - Math.floor(it.p * GAMBLE_OFF), hi: it.p * GAMBLE_UP}; }
  function canBuy(it){ var c = A.cbaS(); if (it.feed) return c.coins < it.p ? 'poor' : 'ok'; if (!it.eat && c.own[it.id]) return 'own'; if (it.eat && A.cbaAte(it.id)) return 'ate'; if (it.need && !c.own[it.need]) return 'need'; if (it.boost){ var bb = A.broodS(); if (bb.gold > 0 || !A.broodReady()) return 'later'; } return c.coins < it.p ? 'poor' : 'ok'; }
  /* Monnie 20 Nov: anything owned can be returned: it leaves The Mount, goes back on the shelf, and the coins paid come back */
  function paidFor(it){ var c = A.cbaS(); c.paid = c.paid || {}; return c.paid[it.id] != null ? c.paid[it.id] : it.p; }
