  var HBW_HIP = [90, 165], HBW_KNEE = [120, 220], HBW_ANG = 28.6, HBW_L = 62.6, HBW_STRIDE = 140, HBW_WPX = 300 / .37 * 1456 / 819, HBW_RAF = 0;
