      bq[1].style.transform = 'translate(' + (-bs * 5).toFixed(1) + '%,' + (-Math.max(0, -bs) * 4).toFixed(1) + '%)';
      bq[3].style.transform = fr < .5 ? 'rotate(6deg)' : 'none';   /* hen head-bob from the throat: thrust forward, then hold while the body catches up */
