  var KID_SCENES = [
    {take: 'baba', lines: [['baba', 'Oi! Put me down!'], ['mama', 'Layla, please help us!']]},
    {take: 'baba', lines: [['baba', 'Make me a cup of tea, Bert!'], ['bert', 'Two sugars?'], ['mama', 'Layla, help!!!']]},
    {take: 'baba', lines: [['mama', 'When can YOU get a mortgage, Bert?'], ['baba', "Don't squander your money on a ransom!"]]},
    {take: 'both', lines: [['mama', "Don't make a cake!!!!!"], ['baba', 'Put the kettle on, Layla!']]},
    {take: 'baba', lines: [['baba', "Don't pay him, Layla! Don't squander your money!"], ['mama', 'PAY HIM, Layla! PAY HIM!']]},
    {take: 'baba', lines: [['bert', 'Returns desk is this way!'], ['baba', 'I want a refund!'], ['mama', 'Layla, I turned the heating on for you!']]},
    {take: 'baba', lines: [['mama', "Who's going to tell you to go to sleep now?!"], ['baba', "You can't sit on your arse while I'm kidnapped!"]]},
    {take: 'baba', lines: [['bert', 'Lovely fresh stock!'], ['baba', 'I am NOT a sausage!'], ['mama', 'Layla, help!!!']]},
    {take: 'both', lines: [['baba', 'At least make me a cup of tea first!'], ['mama', "And DON'T make a cake to celebrate!!!!!"]]},
    {take: 'baba', lines: [['mama', 'Layla, we were FREE!'], ['baba', 'Best bargain you ever had!'], ['layla', 'Bye-bye!']]}
  ];
