      '<div class="xfl"><label for="sra-subj">Subject</label></div><select id="sra-subj" class="xsel" data-sra-sel="s"><option value="">All subjects</option>' +
        subs.map(function(id){ var n = QS.filter(function(q){ return q.subject === id && (!f.p || q.paper === f.p); }).length; return '<option value="' + id + '"' + (f.s === id ? ' selected' : '') + '>' + esc(stitle(id)) + ' (' + n + ')</option>'; }).join("") + '</select>' +
      '<div class="xfl">Show</div><div class="xchips">' + chip("w", "", "All") + chip("w", "new", "Not tried yet") + chip("w", "wrong", "Wrong last time") + '</div>' +
      '<p style="margin:8px 0 0"><b>' + list.length + '</b> question' + (list.length === 1 ? '' : 's') + ' · ' + tried.length + ' tried' + (tried.length ? ' · <b>' + Math.round(right.length / tried.length * 100) + '%</b> right' : '') + '</p>';
    var first = list.filter(function(q){ return !(q.id in r); })[0] || list[0];
    h += '<div class="btns">' + (first ? '<a class="btn primary" href="#/sra/q/' + first.id + '">' + (tried.length && tried.length < list.length ? 'Carry on' : 'Start') + ' (' + esc(first.paper) + ' Q' + first.number + ') ›</a>' : '') +
      (QS.some(function(q){ return r[q.id] === 0; }) && f.w !== "wrong" ? '<button class="btn bad" data-sra="f" data-k="w" data-v="wrong">Show the ones I got wrong</button>' : '') + '</div></div>';
    /* squares */
