    var other = p === "FLK1" ? "FLK2" : "FLK1", oq = QS.filter(function(q){ return q.paper === other; }), oLeft = oq.filter(function(q){ return !(q.id in r); }).length;
    var pc = right + wrong ? Math.round(right / (right + wrong) * 100) : 0;
