      brs.forEach(function(r){ tb += "<tr>" + th.map(function(h, ci){ if (!keep[ci]) return ""; var c = String(r[ci] == null ? "" : r[ci]), e = !c.trim() && ci > 0; return (ci === 0 ? "<th>" : "<td" + (e ? ' class="tdnone"' : '') + ">") + (e ? "–" : inl(c)) + (ci === 0 ? "</th>" : "</td>"); }).join("") + "</tr>"; });
