  var lt = +L.savedAt || 0, rt = +R.savedAt || 0, N = rt > lt ? R : L, O = N === R ? L : R;
  var M = JSON.parse(JSON.stringify(N)), o2 = JSON.parse(JSON.stringify(O)), k;
