  M.todo = syMapFirst(L.todo, R.todo);
  M.logs = syUnionBy(L.logs, R.logs, function(l){ return l.id; }, function(x, y){ return (+y.m || 0) > (+x.m || 0) ? y : x; });
  M.mocks = syUnionBy(L.mocks, R.mocks, function(r){ return [r.d, r.mock, r.paper, r.n, r.c, r.secs].join("|"); });
  M.cheer = Math.max(+L.cheer || 0, +R.cheer || 0);
