  mc.xp = Math.max(+lc.xp || 0, +rc.xp || 0); if (lc.last || rc.last) mc.last = Math.max(+lc.last || 0, +rc.last || 0);
  var lg = L.game || {}, rg = R.game || {}, mg = M.game = M.game || {};
