  o.innerHTML = '<p><b>Saved.</b> Tell Claude ‘banner saved’ and it will be fixed for everyone.</p><button type="button" class="btn primary" data-blact="ok">OK</button>';
  var old = document.getElementById("bltoast"); if (old) old.parentNode.removeChild(old);
