var KIT_DRAWN = {monnie:1, stickers:1, cup:1, pens:1, latte:1, pandan:1, player:1, tote:1, cushion:1, lamp:1, soap:1, sweets:1, clawsocks:1, rec_ss:1, rec_mj:1, skincare:1, toppers:1, calendar:1, colouring:1, crocs:1, charms:1, socks:1, plaque:1, corn:1};
function cbaItemPic(id){
  /* Monnie 20 Nov: real gifts show the EXACT product photos she extracted (img/shop/, shop-images.json), never redraws */
  if (KIT_DRAWN[id] && (window.SQE_SHOPIMG || {})[id]) return '<img class="kitimg prizeimg" src="' + window.SQE_SHOPIMG[id] + '" alt="" width="600" height="600">';
  if (id === "yasmin" || id === "mo") return '<img class="kitimg" src="img/souvenir/' + id + '.webp" alt="" width="300" height="600" style="object-fit:contain">';
  if (id === "parents") return '<img class="kitimg" src="img/shop/parents.webp" alt="Mama and Baba" width="600" height="600">';
  if (KIT_DRAWN[id]) return '<img class="kitimg" src="img/kit/' + id + '.webp" alt="" width="300" height="300">';
  if (id === "corn") return '<svg viewBox="0 0 40 40" aria-hidden="true"><path d="M8 14h24l-3 22H11z" fill="#D9A55B"/><path d="M8 14c4-4 20-4 24 0" fill="#C38B43"/><g fill="#FFD43B"><ellipse cx="15" cy="11" rx="2.4" ry="3"/><ellipse cx="21" cy="9" rx="2.4" ry="3"/><ellipse cx="26" cy="11" rx="2.4" ry="3"/></g><text x="20" y="29" text-anchor="middle" font-size="8" font-weight="700" fill="#7A4E1C">CORN</text></svg>';
  if (id === "ball") return '<img class="kitimg" src="img/kit/ball.webp" alt="" width="300" height="300">';
  if (id === "friend") return '<img class="boluimg" src="img/bolu-drawn.webp" alt="Bolu, a brown hen" width="600" height="600">';
  if (/^(bianca|beefy|brucey)$/.test(id)) return '<img class="boluimg" src="img/hen-' + id + '.webp" alt="' + ({bianca:"Bianca, a speckled hen", beefy:"Beefy, a stripy hen", brucey:"Brucey, a grey-blue hen"})[id] + '" width="600" height="600">';
  if (id === "bonnie") return '<img class="bonnieimg" src="img/bonnie.webp" alt="Jiminey, a ginger lop-eared rabbit" width="321" height="268">';
  if (id === "parents") return '<span class="parentscard" style="display:flex;align-items:center;justify-content:center;width:100%;height:100%;min-height:60px;border-radius:12px;background:#FFE3EC;font-size:1.6em" role="img" aria-label="Mama and Baba">👩&zwj;❤️&zwj;👨</span>'; /* placeholder until img/shop/parents.webp exists (shop-images.json; build.py drops missing files) */
  if (/^(swing|cookies|nestbox|goldcorn|palace|coop)$/.test(id)) return '<img class="kitimg" src="img/shop/' + id + '.webp" alt="" width="600" height="600">';
  return CBA_PICS[id] ? '<svg viewBox="0 0 40 40" aria-hidden="true">' + CBA_PICS[id] + '</svg>' : '';
}
function cbaFlock(){
  var c = cbaS(), f = {eggs:[], chicks:[], hens:[]};
  Object.keys(c.eggs).forEach(function(k){ if (!TBYKEY[k]) return; var st = cbaStage(k); (st === 3 ? f.hens : st === 2 ? f.chicks : f.eggs).push(k); });
  return f;
}
function cbaScene(small){
  var c = cbaS(), m = cbaMood(), L = m.L, o = c.own, f = cbaFlock(), wx = weatherNow();
  var nw = function(id){ return CBNEW === id ? " new" : ""; };
  var pic = function(id, cls){ return '<span class="sacc ' + cls + nw(id) + '">' + cbaItemPic(id) + '</span>'; };
  var h = '<div class="scene mood-' + m.m + ' wx-' + wx.k + (o.palace ? ' haspalace' : '') + (small ? ' small' : '') + '"><span class="ssun"></span><span class="scloud c1"></span><span class="scloud c2"></span><span class="shill"></span><span class="sfence"></span>' + weatherPic(wx);
  var sign = o.plaque ? '<span class="splaque' + nw("plaque") + '"><span>Welcome to</span><b>Cluckington Palace</b></span>' : '';
  if (o.palace) h += '<div class="sitem spalace' + nw("palace") + '">' + cbaItemPic("palace") + sign + '</div>';
  else if (o.coop) h += '<div class="sitem scoop' + nw("coop") + '">' + cbaItemPic("coop") + sign + '</div>';
  else if (sign) h += '<div class="sitem sfsign">' + sign + '</div>';
  if (o.clawsocks) h += '<div class="sitem sline' + nw("clawsocks") + '"><i class="sl"></i><span class="sock s1">' + cbaItemPic("clawsocks") + '</span><span class="sock s2">' + cbaItemPic("clawsocks") + '</span></div>';
  /* Britney's shelf: decor that sits indoors-ish, with the record player on top */
  var shelf = ["skincare", "lamp", "soap", "sweets", "toppers", "colouring", "calendar"].filter(function(id){ return o[id]; });
  var recs = ["rec_ss", "rec_mj"].filter(function(id){ return o[id] && o.player; });
  if (shelf.length || o.player || o.tote || o.stickers){
    h += '<div class="sitem sshelf"><span class="stop">' + (o.player ? pic("player", "splayer") : '') + recs.map(function(id){ return pic(id, "srec"); }).join("") +
      (recs.length ? '<span class="snotes" aria-hidden="true"><i>♪</i><i>♫</i><i>♪</i><i>♬</i></span>' : '') + '</span><span class="sbox">' +
      (o.stickers ? '<span class="sstick' + nw("stickers") + '"><img src="img/kit/stickers.webp" alt="" width="300" height="300" style="position:absolute;right:-10px;bottom:-12px;width:38px;height:auto"></span>' : '') +
      '<span class="srow">' + shelf.map(function(id){ return pic(id, "sthing"); }).join("") + '</span></span>' + (o.tote ? pic("tote", "stote") : '') + '</div>';
  }
  f.hens.slice(0, 4).forEach(function(k, i){ h += '<div class="sitem sminihen" style="right:' + (4 + i * 9) + '%" title="' + esc(tnum(TBYKEY[k])) + '">' + cbaHen("mini") + '</div>'; });
  if (f.eggs.length) h += '<div class="sitem snest" title="Topic eggs waiting to hatch">' + cbaNest(f.eggs.slice(0, 3).map(function(){ return cbaEgg("wob"); }).join("")) + '</div>';
  f.chicks.slice(0, 5).forEach(function(k, i){ h += '<div class="sitem schick" style="left:' + (6 + i * 7) + '%;animation-delay:-' + i * 0.7 + 's" title="' + esc(tnum(TBYKEY[k])) + '">' + cbaChick() + '</div>'; });
  if (cbaAte("corn")) h += '<div class="sitem scorn' + nw("corn") + '"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div>';
  if (o.cushion) h += '<div class="sitem scush' + nw("cushion") + '">' + cbaItemPic("cushion") + '</div>';
  var bl = britneyLook().has; var acc = (o.cup && bl.indexOf("cup") < 0 ? pic("cup", "scup") : '') + (o.pens && bl.indexOf("pens") < 0 ? pic("pens", "spens") : '') + (cbaAte("latte") ? pic("latte", "streat") : cbaAte("pandan") ? pic("pandan", "streat") : '');
  if (L.away) h += '<a class="sitem stracy saway" href="#/town/butcher" aria-label="Britney is at Bert\'s Butchers">' + cbaNest('') + '</a>';
  else {
    if (m.m === "sad2" || m.m === "hungry" || m.m === "door" || m.m === "ill") h += '<span class="srain" aria-hidden="true"><i></i><i></i><i></i></span>';
    h += '<button class="sitem stracy' + (m.m === "ill" ? " sill" : "") + '" data-act="cbapet" aria-label="Pat Britney">' + (m.m === "ill" ? '<span class="sblanket"></span>' : '') + britneyImg(m.cls + (CBNEW && m.m !== "ill" ? " jump" : "")) + acc + '</button>';
  }
  if (o.friend) h += '<div class="sitem slouise' + nw("friend") + '">' + cbaItemPic("friend") + '</div>';
  ["bianca", "beefy", "brucey"].forEach(function(id){ if (o[id]) h += '<div class="sitem shen3 s' + id + nw(id) + '">' + cbaItemPic(id) + '</div>'; });
  if (o.swing) h += '<div class="sitem sswing' + nw("swing") + '">' + cbaItemPic("swing") + '</div>';
  if (o.nestbox) h += '<div class="sitem snestbox' + nw("nestbox") + '">' + cbaItemPic("nestbox") + '</div>';
  if (o.bonnie) h += '<div class="sitem sbonnie' + nw("bonnie") + '">' + cbaItemPic("bonnie") + '</div>';
  if (cbaAte("cookies") && !L.away && (L.stage === "hen" || L.stage === "chick")) h += '<div class="sitem scookies' + nw("cookies") + '">' + cbaItemPic("cookies") + '</div>';
  h += broodScene();
  if (o.ball) h += '<div class="sitem sball">' + cbaItemPic("ball") + '</div>';
  h += '</div>';
  /* plain row under the picture: coins, how she is, who is in the picture */
  var who = L.away ? "Britney isn't here: Bert the butcher has taken her to his shop."
    : "In the picture: " + listAnd(["Britney (the white hen)"].concat(o.friend ? ["her best friend Bolu (the brown hen)"] : [], o.bianca ? ["Bianca (the speckled hen)"] : [], o.beefy ? ["Beefy (the stripy hen)"] : [], o.brucey ? ["Brucey (the grey-blue hen)"] : [], o.bonnie ? ["Jiminey the rabbit"] : [], broodWho(), (f.eggs.length || f.chicks.length || f.hens.length) ? ["your topic " + listAnd([].concat(f.eggs.length ? ["eggs (in the nest)"] : [], f.chicks.length ? ["chicks"] : [], f.hens.length ? ["hens (by the fence)"] : []))] : [])) + ".";
  h += '<div class="sbar"><span class="spill">' + cbaCoin() + ' <b>' + c.coins + '</b> coins</span><span class="spill">' + m.e + ' ' + esc(henName(L)) + ': ' + esc(m.l) + '</span>' + (small ? '' : '<a class="spill shop" href="#/palace/shop">🛒 Shop</a>') + '</div>' +
    '<p class="swho">' + esc(who) + (L.away ? ' <a href="#/town/butcher">See Bert\'s shop ›</a>' : '') + '</p>' + (small ? '' : '<p class="swx">' + esc(wx.why) + '</p>');
  return h;
}


/* ---------- landing: farm + level map ---------- */
function cbaTopicHead(x){
  var s = x.s, t = x.t, r = topicRes(s, t);
  return '<div class="card cbahead' + skinOf(s.id) + '"><div class="small muted"><a href="#/syllabus">Syllabus</a> › <a href="#/subject/' + s.id + '">' + esc(s.title) + '</a></div><div class="topichead"><h2>' + esc(t.title) + '</h2><div class="viewtabs">' +
    '<a href="#/topic/' + s.id + '/' + t.id + '">Notes</a>' +
    (r.fw ? '<a href="#/topic/' + s.id + '/' + t.id + '/framework">🗺️ Framework</a>' : '<span class="vt-off">🗺️ Framework</span>') +
    (NO_CT ? '' : r.ct ? '<a href="#/topic/' + s.id + '/' + t.id + '/cartoon">🖼️ Cartoon</a>' : '<span class="vt-off">🖼️ Cartoon</span>') +
    '<a href="#/cba/' + s.id + '/' + t.id + '" class="on">🎯 CBA</a></div></div><p class="small muted" style="margin:6px 0 0">Not up to reading today? CBA teaches you the whole topic one small piece at a time and tests you as you go. Finishing every round counts as reading the notes.</p></div>';
}
function viewCBA(r){
  var c = cbaS();
  if (r[1] === "shop" && !r[2]){ setTimeout(function(){ location.replace("#/palace/shop"); }, 0); return '<div class="card">Opening Hen Bargains…</div>'; }
  if (r[1] && r[2]){
    var x = TBYKEY[r[1] + "/" + r[2]];
    if (!x || !cbaReady(x)) return '<div class="cbag"><div class="cbacard"><h2>This level is coming soon</h2><a class="btn" href="#/syllabus">Back to the syllabus</a></div></div>';
    if (!CB || CB.key !== x.key) cbaStart(x);
    return cbaTopicHead(x) + cbaLevel();
  }
  var pick = cbaPick(), m = cbaMood(), f = cbaFlock(), h = '<div class="cbag">';
  h += '<a class="cbapal" href="#/palace"><span class="cpic">' + henPic(m.L, m) + '</span><span class="ctx"><b>Britney at The Mount</b><span>' + esc(m.e + " " + henName(m.L) + ": " + m.l) + '. Feed her at The Mount and spend your coins in Hen Bargains in Peckham.</span></span><span class="spill coin">' + cbaCoin() + ' <b>' + c.coins + '</b></span></a>';
  h += '<div class="cbabig">' + (pick ? '<a class="cbabtn go" href="#/cba/' + pick.s.id + '/' + pick.t.id + '">🎲 You pick for me<small>' + esc(pick.t.title) + (cbaRoundNo(pick.key) ? " · round " + (cbaRoundNo(pick.key) + 1) + " of " + cbaRounds(pick.key) : "") + '</small></a>' : '') +
    '<button class="cbabtn" data-act="cbamap">🧺 I\'ll pick<small>Tap a nest on the map</small></button></div>';
  h += '<div class="cbaflock"><span>' + cbaEgg("ico") + ' <b>' + f.eggs.length + '</b> egg' + (f.eggs.length === 1 ? '' : 's') + '</span><span>' + cbaChick("ico") + ' <b>' + f.chicks.length + '</b> chick' + (f.chicks.length === 1 ? '' : 's') + '</span><span>' + cbaHen("ico") + ' <b>' + f.hens.length + '</b> grown</span><span>🔥 <b>' + cbaStreak() + '</b> day' + (cbaStreak() === 1 ? '' : 's') + ' in a row</span></div>';
  h += '<p class="cbahow">Study a topic in any way (Today, cards, Quick fire, Q&amp;A, podcast or a CBA level) = a topic egg ' + cbaEgg("ico") + ' · Pass its Quick fire = it hatches ' + cbaChick("ico") + ' · Rate the topic green 🟢 = a grown chicken ' + cbaHen("ico") + '</p>';
  if (f.eggs.length) h += '<div class="cbahatch">' + f.eggs.slice(0, 3).map(function(k){ var x = TBYKEY[k]; return '<a href="#/quick/' + x.s.id + '/' + x.t.id + '">' + cbaEgg() + '<span>Hatch your <b>' + esc(x.t.title) + '</b> egg: do its Quick fire ›</span></a>'; }).join("") + '</div>';
  h += '<div class="cbamap" id="cbamap">';
  var soon = [];
  SUBJ.forEach(function(s){
    var ready = s.topics.filter(function(t){ return cbaReady({key:s.id + "/" + t.id}); });
    if (!ready.length){ soon.push(s.title); return; }
    h += '<div class="msub"><h3>' + esc(s.title) + '</h3><div class="mpath">';
    s.topics.forEach(function(t, i){
      var k = s.id + "/" + t.id;
      if (!cbaReady({key:k})){ h += '<span class="mnode soon" title="Coming soon">' + cbaNest('') + '<span class="mlab">' + (i + 1) + '. ' + esc(t.title) + '</span><span class="mst">Coming soon</span></span>'; return; }
      var st = cbaStage(k), rn = cbaRoundNo(k), inner, lab;
      if (st === 3){ inner = cbaHen("mini"); lab = cbaHen("ico") + " Grown"; }
      else if (st === 2){ inner = cbaChick(); lab = cbaChick("ico") + " Hatched"; }
      else if (st === 1){ inner = cbaEgg("wob"); lab = cbaEgg("ico") + " Egg"; }
      else { inner = ''; lab = rn ? "Round " + (rn + 1) + " of " + cbaRounds(k) : cbaRounds(k) + " rounds"; }
      h += '<a class="mnode st' + st + (pick && pick.key === k ? ' next' : '') + '" href="#/cba/' + s.id + '/' + t.id + '">' + cbaNest(inner) + '<span class="mlab">' + (i + 1) + '. ' + esc(t.title) + '</span><span class="mst">' + lab + '</span></a>';
    });
    h += '</div></div>';
  });
  if (soon.length) h += '<div class="msoon"><b>More farms coming soon:</b> ' + soon.map(esc).join(" · ") + '</div>';
  return h + '</div></div>';
}

/* ---------- shop ---------- */
function cbaShop(){
  var c = cbaS();
  var h = '<div class="cbag"><div class="cbatop"><a class="cbaback" href="#/cba">‹ Back to the farm</a><b class="cbattl">Britney\'s shop</b></div>' + cbaScene(true);
  CBNEW = "";
  h += '<p class="cbahow">Every prize is for Britney. She wears it or shows it off on the farm.</p><div class="cbashop">';
  CBA_SHOP.forEach(function(it){
    var have = !it.eat && !it.feed && c.own[it.id], need = it.need && !c.own[it.need], btn;
    if (it.feed) btn = (c.coins < it.p ? '<button class="btn" disabled>Need ' + (it.p - c.coins) + ' more</button>' : '<button class="btn primary" data-act="cbabuy" data-i="' + it.id + '">Buy · ' + it.p + '</button>') + '<span class="sfeedn">You have ' + plural(feedLeft(), "bag") + '</span>';
    else if (have) btn = '<span class="sown">✓ Owned</span>';
    else if (it.eat && cbaAte(it.id)) btn = '<span class="sown">Yum! More tomorrow</span>';
    else if (need) btn = '<span class="sneed">Buy the ' + esc(cbaItem(it.need).n) + ' first</span>';
    else if (c.coins < it.p) btn = '<button class="btn" disabled>Need ' + (it.p - c.coins) + ' more</button>';
    else btn = '<button class="btn primary" data-act="cbabuy" data-i="' + it.id + '">' + (it.eat ? 'Feed her' : 'Buy') + '</button>';
    h += '<div class="sitm' + (have ? ' have' : '') + (need ? ' locked' : '') + '"><span class="spic">' + cbaItemPic(it.id) + '</span><b>' + esc(it.n) + '</b><span class="sdesc">' + esc(it.d) + '</span>' + (have ? '' : '<span class="sprice">' + it.p + ' ' + cbaCoin() + '</span>') + btn + '</div>';
  });
  return h + '</div><p class="cbahow">CBA coins: 2 ' + cbaCoin() + ' for each right answer (very fast answers earn none), 3 extra for every 3 in a row, 5 for each round, and 20 for finishing a level (10 for a replay). Everything else you revise on the site earns coins too.</p></div>';
}
function cbaBuy(id){
  var c = cbaS(), it = cbaItem(id); if (!it || c.coins < it.p || (it.need && !c.own[it.need])) return;
  if (it.boost){ var bb = broodS(); if (bb.gold > 0 || !broodReady()) return; bb.gold += it.boost; }
  else if (it.feed){ c.feed = feedLeft() + 1; } /* 20 Nov: one bag of feed; she feeds it at The Mount (no auto-feed) */
  else if (it.eat){ if (cbaAte(id)) return; c.ate[id] = c.fed = Date.now(); c.lastAte = id; }
  else { if (c.own[id]) return; c.own[id] = Date.now(); }
  c.coins -= it.p; CBNEW = id; save();
}

/* ---------- playing a level ---------- */
function cbaWords(s){ return String(s || "").split(/\s+/).filter(Boolean).length; }
function cbaLock(){ var st = CB && CB.steps[CB.queue[0]]; return st ? Math.min(4000, 1500 + 40 * cbaWords(st.l)) : 0; }
function cbaLockBtn(id, act, label, start, dur){
  var left = Math.max(0, start + dur - Date.now());
  if (left) setTimeout(function(){ var b = document.getElementById(id); if (b && CB && Date.now() >= start + dur - 20) b.disabled = false; }, left + 30);
  return '<button id="' + id + '" class="btn primary big cbalock" data-act="' + act + '"' + (left ? ' disabled' : '') + ' style="--d:' + dur + 'ms;--o:-' + (dur - left) + 'ms"><i class="fill"></i><span>' + label + '</span></button>';
}
function cbaLevel(){
  var x = CB.x, nR = cbaRounds(CB.key), rsz = cbaQueue(CB.key, CB.rd).length, rdone = Object.keys(CB.right).length, c = cbaS(), pop = CBPOP; CBPOP = 0;
  var pips = ''; for (var p = 0; p < nR; p++) pips += '<i class="' + (p < CB.rd || (p === CB.rd && !CB.queue.length) ? 'on' : p === CB.rd ? 'cur' : '') + '"></i>';
  var henCls = "ok";
  if (CB.ans !== null) henCls = CB.ans === 0 ? (CB.quick ? "ok" : "happy jump") : "sad";
  else if (!CB.queue.length) henCls = "happy jump";
  var head = '<div class="cbag' + skinOf(x.s.id) + '"><div class="cbatop"><a class="cbaback" href="#/topic/' + x.s.id + '/' + x.t.id + '">‹ Notes</a><span class="cbattl">' + esc(tnum(x)) + ': ' + esc(x.t.title) + '</span><span class="spill coin">' + cbaCoin() + ' <b>' + c.coins + '</b>' + (pop ? '<span class="cpop">+' + pop + ' ' + cbaCoin() + '</span>' : '') + '</span></div>' +
    '<div class="cbaprog"><div class="ctrack"><i style="width:' + (rdone / rsz * 100).toFixed(1) + '%"></i></div><div class="cpips" title="Rounds">' + pips + '</div></div>' +
    '<div class="small cbameta">Round ' + (CB.rd + 1) + ' of ' + nR + ' · ' + rdone + ' of ' + rsz + ' right' + (CB.combo > 1 ? ' · 🔥 ' + CB.combo + ' in a row' : '') + '</div>';
  var mini = '<div class="cbamini">' + cbaHen(henCls, cbaWear()) + '</div>';
  if (!CB.queue.length && CB.rd < nR - 1) return head + '<div class="cbacard win">' + mini + '<h2>Round ' + (CB.rd + 1) + ' done! 🎉</h2><p>' + (CB.rd + 1 === nR - 1 ? 'Just one round left.' : (nR - CB.rd - 1) + ' rounds left.') + ' You\'ve earned <b>' + CB.coins + ' ' + cbaCoin() + '</b> so far (including a 5 ' + cbaCoin() + ' round bonus).</p><p class="small muted">Fancy a break? Your place is saved.</p><div class="btns cbac"><button class="btn primary big" data-act="cbaround">Next round ›</button><a class="btn big" href="#/cba" data-act="cbanext">Back to the farm</a></div></div></div>';
  if (!CB.queue.length){
    var dn = CB.steps.length, nx = cbaPick();
    return head + '<div class="cbacard win"><div class="bigegg">' + cbaEgg("wob") + '</div><h2>' + esc(CBA_CHEERS[(dn + c.coins) % CBA_CHEERS.length]) + '</h2><p>' + (CB.firstEgg ? 'A new <b>topic egg</b> for ' + esc(x.t.title) + ' is on the farm! It hatches into a chick when you pass this topic\'s Quick fire.' : CB.firstDone ? 'Level finished! Your ' + esc(x.t.title) + ' egg was already on the farm from your other revision. Pass its Quick fire to hatch it.' : 'Lovely refresher. Your egg for this topic is safe on the farm.') + '</p><p>You earned <b>' + CB.coins + ' ' + cbaCoin() + '</b> on this go. Best run in a row: <b>' + CB.best + '</b>.</p>' +
      '<div class="btns cbac"><a class="btn primary big" href="#/quick/' + x.s.id + '/' + x.t.id + '" data-act="cbanext">Hatch it: Quick fire</a>' + (nx && nx.key !== CB.key ? '<a class="btn big" href="#/cba/' + nx.s.id + '/' + nx.t.id + '" data-act="cbanext">Next level ›</a>' : '') + '<a class="btn big" href="#/cba" data-act="cbanext">Back to the farm</a></div></div></div>';
  }
  var i = CB.queue[0], st = CB.steps[i];
  if (CB.phase === "learn"){
    if (!CB.learnAt) CB.learnAt = Date.now();
    return head + '<div class="cbacard learn">' + mini + '<div class="cbatag">💡 ' + (CB.retry[i] ? 'Quick reminder' : 'Learn this') + '</div><div class="cbatext">' + inl(st.l) + '</div><div class="btns cbac">' + cbaLockBtn("cbaqbtn", "cbaq", "Quiz me ›", CB.learnAt, cbaLock()) + '</div></div></div>';
  }
  if (!CB.qAt) CB.qAt = Date.now();
  if (!CB.ord) CB.ord = shuffle([0, 1, 2, 3]);
  var h = head + '<div class="cbacard ask">' + mini + '<div class="cbatag">❓ Your turn</div><div class="cbaq">' + inl(st.q) + '</div><div class="opts">';
  CB.ord.forEach(function(oi, pos){ var cls = "opt"; if (CB.ans !== null){ if (oi === 0) cls += " right"; else if (oi === CB.ans) cls += " wrong"; } h += '<button class="' + cls + '" data-act="cbapick" data-o="' + oi + '"' + (CB.ans !== null ? " disabled" : "") + '><span class="L">' + "ABCD"[pos] + '</span><span>' + inl(st.o[oi]) + '</span></button>'; });
  h += '</div>';
  if (CB.ans !== null){
    var ok = CB.ans === 0, msg;
    if (ok && CB.quick) msg = '<b class="cq">✓ Right, but too quick! Read it properly for coins ' + cbaCoin() + '</b>';
    else if (ok) msg = '<b class="cg">✓ Yes! +' + CB.got + ' ' + cbaCoin() + (CB.bonus ? ' · 🔥 ' + CB.combo + ' in a row: +' + CB.bonus + ' bonus' : '') + '</b>';
    else msg = '<b class="cb">✗ Not quite. This one pops back at the end of the round for another quick go.</b>';
    h += '<div class="cbafb ' + (ok ? 'ok' : 'no') + '">' + msg + '<div class="cbawhy"><b>Why:</b> ' + inl(st.e) + '</div></div><div class="btns cbac">' + cbaLockBtn("cbanbtn", "cbanext2", "Next ›", CB.ansAt, 1000) + '</div>';
  }
  return h + '</div></div>';
}
function cbaPay(n){ if (!n) return; var c = cbaS(); c.coins += n; if (CB) CB.coins += n; CBPOP += n; }
function cbaAnswer(o){
  var i = CB.queue[0], ok = o === 0, c = cbaS(), now = Date.now();
  CB.ans = o; CB.quick = now - (CB.qAt || 0) < CBA_QUICK; CB.got = 0; CB.bonus = 0; CB.ansAt = now;
  c.days[ymd()] = 1; c.last = now; c.recent.push(ok ? 1 : 0); if (c.recent.length > 10) c.recent = c.recent.slice(-10);
  if (ok){
    CB.right[i] = 1; c.xp = (+c.xp || 0) + 10;
    if (!CB.quick){ CB.combo++; CB.best = Math.max(CB.best, CB.combo); CB.got = 2; if (CB.combo % 3 === 0) CB.bonus = 3; }
  } else { CB.combo = 0; CB.retry[i] = 1; }
  cbaPay(CB.got + CB.bonus);
  if (CB.got + CB.bonus){ CBPOP -= CB.got + CB.bonus; POPQ.push(CB.got + CB.bonus); schedulePop(); } /* QA 21 Nov (Layla): float the coins beside her answer, not in the top bar */
  save();
}
function cbaAdvance(){
  var i = CB.queue.shift(); if (CB.ans !== 0) CB.queue.push(i);
  CB.ans = null; CB.ord = null; CB.phase = "learn"; CB.learnAt = 0; CB.qAt = 0; CB.quick = false;
  if (!CB.queue.length){
    var c = cbaS(), k = CB.key; c.prog[k] = CB.rd + 1; cbaPay(5);
    if (CB.rd >= cbaRounds(k) - 1){
      CB.firstEgg = !c.eggs[k]; CB.firstDone = !c.done[k];
      if (!c.done[k]){ c.done[k] = Date.now(); c.xp = (+c.xp || 0) + 50; }
      cbaPay(CB.firstDone ? 20 : 10);
      var rr = trec(k) || {n:0, conf:null, at:0}; if (!rr.at || ymd(new Date(rr.at)) !== ymd()) rr.n++; rr.at = Date.now(); S.done[k] = rr; /* 21 Nov Monnie: finishing CBA no longer marks the topic amber; it stays unrated until she taps a face */
      if (!c.eggs[k]) c.eggs[k] = Date.now();
      S.todo = S.todo || {}; S.todo[k + "|notes"] = S.todo[k + "|notes"] || Date.now(); S.todo[k + "|quick"] = S.todo[k + "|quick"] || Date.now();
    }
  }
  save();
}
/* ============ REVISION TIMETABLE ============ */
