  var dots = rs.map(function(r){ var dn = !!(S.todo && S.todo[r.k]); if (dn) n++; if (!dn && !nx && r.d >= t) nx = r; return '<i class="rd' + (dn ? ' on' : (r.d < t ? ' miss' : '')) + '" title="Review ' + (rs.indexOf(r) + 1) + ' (' + lab[r.gap] + '), ' + esc(fmtDate(r.d)) + (dn ? ': done' : '') + '"></i>'; }).join("");
