document.addEventListener("keydown", function(e){ if (e.key === "Enter" && e.target && e.target.classList && e.target.classList.contains("qck-in")){ e.preventDefault(); var bx = e.target.closest(".qck"), bt = bx && bx.querySelector(".qck-check"); if (bt && !bt.hidden) bt.click(); } });
