  if (cd){ var hl = ch[0] && /^##\s/.test(ch[0]) ? ch[0] : "", rest2 = hl ? ch.slice(1) : ch;
    body = (hl ? md(hl) : '') + cd + '<details class="biread nsfull"><summary>📖 Full notes</summary><div class="bibody">' + md(rest2.join("\n")) + '</div></details>' + (d.q ? nckHTML(head) : ''); }
  if (qcs.length){ var placed = {}; body = body.replace(/<p>@@QCK(\d+)@@<\/p>/g, function(m, n){ placed[n] = 1; return qckHTML(+n); }).replace(/@@QCK\d+@@/g, ''); qcs.forEach(function(c){ if (!placed[c.n]) body += qckHTML(c.n); }); }
