      (st.yes || st.no ? '<div class="fwflow">' + (st.yes ? '<span class="y">Yes → ' + esc(st.yes) + '</span>' : '') + (st.no ? '<span class="n">No → ' + esc(st.no) + '</span>' : '') + '</div>' : '') + '</div>';
