  return fwkHTML(m.title, m.sub, (m.branches || []).map(function(b, bi){ return {h:b.h, c:cols[bi % cols.length], html:'<ul class="fwk-pts">' + (b.pts || []).map(function(pt){ return '<li>' + inl(pt) + '</li>'; }).join('') + '</ul>'}; }), skin, k + '-m');
