  var strip = '<div class="qsq strip">' + QZ.items.map(function(q, n){ var aa = QZ.ans[n]; return '<button class="sq' + (aa ? (aa.ok ? " ok" : " bad") : "") + (n === QZ.i ? " cur" : "") + '" data-act="qgo" data-n="' + n + '" title="Question ' + (n + 1) + '">' + (n + 1) + '</button>'; }).join("") + '</div>';
  var qtk = QZ.tkey && TBYKEY[QZ.tkey], qsk2 = qtk ? skinOf(qtk.s.id) : ""; /* examqs: sweet skin for a Business Law 1 topic set */
