    property: '<rect width="12" height="12" fill="#A9E4B8"/><path d="M0,12 L12,0" stroke="#2B8A5B" stroke-width="2.2"/>',
    crimlaw: '<rect width="12" height="12" fill="#EEF8FF"/><path d="M0,0 L12,12 M12,0 L0,12" stroke="#BFE0F5" stroke-width="1.2"/>',
