var PODS = (function(){ var p = window.SQE_PODCASTS, out = {}; if (!p || typeof p !== "object") return out; for (var k in p){ var e = p[k]; if (e && typeof e.file === "string" && e.file && TBYKEY[k]){ out[k] = {file:e.file, mins:+e.mins || 0}; var ps = Array.isArray(e.parts) ? e.parts.filter(function(q){ return q && typeof q.file === "string" && q.file; }).map(function(q){ return {file:q.file, secs:+q.secs || 0}; }) : []; if (ps.length > 1){ out[k].parts = ps; var ts = ps.reduce(function(n, q){ return n + q.secs; }, 0); if (ts && !out[k].mins) out[k].mins = Math.round(ts / 60); } } } return out; })();
