var TLSKIP = "a,button,h1,h2,h3,h4,h5,h6,summary,svg,textarea,select,option,label,input,script,style,code,thead,[contenteditable],.nck,.qf,.cbaq,.opts,.opt,.nc-ref,.bistrip,.bigrid,.scard-h,.mmb,.fwk-h,.fwk-title,.fwk-sub,.cardq,.tlink";
