/* 21 Nov 02:12 Monnie: when she ticks the last activity of the day, a felt-tip "Well done!" card with streamers and confetti,
   then the banner scrolls into view and Layla jumps up to her new cloud. Shown once per day (S.celeb = that day). */
function dayCeleb(){
  if (document.querySelector(".celeb")) return;
  var cols = ["#FF4FA3", "#FFD43B", "#3DBBFF", "#7CD64B", "#B07CFF", "#FF8A3D"], conf = "", str = "";
  for (var i = 0; i < 46; i++) conf += '<i class="cf" style="left:' + (Math.random() * 100).toFixed(1) + '%;background:' + cols[i % cols.length] + ';animation-delay:' + (Math.random() * 1.2).toFixed(2) + 's;animation-duration:' + (2.2 + Math.random() * 1.6).toFixed(2) + 's;--r:' + Math.round(Math.random() * 720 - 360) + 'deg"></i>';
  for (var j = 0; j < 6; j++) str += '<svg class="cstr cstr' + j + '" viewBox="0 0 40 160" aria-hidden="true"><path d="M20 0 C2 20 38 40 20 60 S2 100 20 120 S38 150 20 160" fill="none" stroke="' + cols[j] + '" stroke-width="7" stroke-linecap="round"/><path d="M20 0 C2 20 38 40 20 60 S2 100 20 120 S38 150 20 160" fill="none" stroke="#2A1B2E" stroke-width="1.6" stroke-linecap="round" stroke-dasharray="1 9"/></svg>';
  var o = document.createElement("div"); o.className = "celeb"; o.setAttribute("role", "dialog"); o.setAttribute("aria-label", "Well done");
  o.innerHTML = '<div class="cconf" aria-hidden="true">' + conf + '</div><div class="ccard">' + str + '<div class="cbig">Well done, Layla!</div><div class="csub">You did all of today\'s activities!</div><button type="button" class="btn primary cgo">See Layla jump up a cloud ›</button></div>';
  document.body.appendChild(o);
  var go = function(){ if (!o.parentNode) return; o.classList.add("out"); setTimeout(function(){ if (o.parentNode) o.parentNode.removeChild(o); }, 350);
    var st = document.querySelector(".nbsvg") || document.querySelector(".stsvg"); if (!st) return; try { window.scrollTo({top:0, behavior:"smooth"}); } catch(e){ window.scrollTo(0, 0); }
    setTimeout(function(){ var l = document.querySelector(".nbsvg .nblayg") || document.querySelector(".stsvg .stlayla"); if (!l) return; try { var sn = Math.min(presentStreak(), PRESENT_STEPS), P = function(i){ return i <= 0 ? [85, 588] : [176 + (i - 1) * 118, 469 - (i - 1) * 27]; }, a0 = P(sn - 1), a1 = P(sn); l.style.setProperty("--jx", (a0[0] - a1[0]) + "px"); l.style.setProperty("--jy", (a0[1] - a1[1]) + "px"); } catch(eJ){} l.classList.remove("stjump"); void l.getBBox(); l.classList.add("stjump"); var s2 = l.closest("svg"); if (s2) s2.classList.add("stglow"); setTimeout(function(){ if (s2) s2.classList.remove("stglow"); l.classList.remove("stjump"); }, 2800); }, 700); };
  o.querySelector(".cgo").addEventListener("click", go);
  o.addEventListener("click", function(e){ if (e.target === o) go(); });
}
window.SQE_CELEB = dayCeleb;
